SELECT c.c_customer_id, c.c_first_name, c.c_last_name, (c.c_birth_year * 10000 + c.c_birth_month * 100 + c.c_birth_day) AS birth_date_int, CASE WHEN c.c_preferred_cust_flag = 'N' THEN 'Preferred' WHEN c.c_preferred_cust_flag = 'N' THEN 'Standard' ELSE 'Unknown' END AS customer_type, wp.wp_url, wp.wp_char_count, wp.wp_char_count * 2 AS double_char_count, CASE WHEN wp.wp_type = 'order                                             ' THEN 'Home Page' WHEN wp.wp_type = 'protected                                         ' THEN 'Product Page' ELSE 'Other Page' END AS page_category, (wp.wp_char_count + wp.wp_link_count + wp.wp_image_count) AS total_elements FROM customer c JOIN web_page wp ON wp.wp_customer_sk = c.c_customer_sk WHERE c.c_birth_year = 1936 AND wp.wp_type = 'feedback                                          '
